_rankCar:
const _rankCar = { pos: 0, vel: 0, raf: 0, gen: 0, depth: 0, watchdog: 0, jumpTimer: 0,
  geom: null, atmos: null, nearest: -1, mine: 0, landed: -1, arrival: null, fades: null,
  motionQuery: null, ro: null };

RANKS:
const RANKS = [
  { min:1,  max:4,        name:'ROOKIE' },
  { min:5,  max:9,        name:'TRAINEE' },
  { min:10, max:14,       name:'ATHLETE' },
  { min:15, max:19,       name:'COMPETITOR' },
  { min:20, max:29,       name:'ELITE' },
  { min:30, max:39,       name:'VETERAN' },
  { min:40, max:49,       name:'MASTER' },
  { min:50, max:Infinity, name:'LEGEND' }
];

RANK_EMBLEM_FILE:
const RANK_EMBLEM_FILE = {
  ROOKIE:     'rank-1.png',
  TRAINEE:    'rank-2.png',
  ATHLETE:    'rank-3.png',
  COMPETITOR: 'rank-4.png',
  ELITE:      'rank-5.png',
  VETERAN:    'rank-6.png',
  MASTER:     'rank-7.png',
  LEGEND:     'rank-8.png'
};

rankNow:
function rankNow(){
  return (typeof performance !== 'undefined' && performance && typeof performance.now === 'function')
    ? performance.now() : Date.now();
}

rankReducedMotion:
function rankReducedMotion(){
  try{
    if(!_rankCar.motionQuery && window.matchMedia) _rankCar.motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    return !!(_rankCar.motionQuery && _rankCar.motionQuery.matches);
  }catch(e){ return false; }
}

rankRubber:
function rankRubber(overshoot, dimension){
  const d = Math.max(1, dimension), x = Math.abs(overshoot);
  return (overshoot < 0 ? -1 : 1) * (1 - 1 / (x * RANK_MOTION.rubber / d + 1)) * d;
}

rankSettleTarget:
function rankSettleTarget(startPos, dragPx, vPx, step, heading, lead){
  const M = RANK_MOTION, last = RANKS.length - 1;
  const s = Math.max(1, step || 1);
  const clamp = i => Math.max(0, Math.min(last, i));
  const start = clamp(Math.round(startPos));
  const home = heading === undefined ? start : clamp(heading);
  const dx = dragPx || 0, v = vPx || 0;
  const travel = dx + (lead || 0);                     
  const at = startPos - dx / s;                        
  const dragDir = travel < 0 ? 1 : -1, throwDir = v < 0 ? 1 : -1;

  const ahead = v * travel > 0 ? v * M.projectMs : 0;
  const far = Math.abs(travel) >= M.flickDistance && Math.abs(travel + ahead) >= Math.max(M.commitMin, M.commitFraction * s);
  if(Math.abs(v) >= M.flickVelocity){
    if(travel !== 0 && throwDir !== dragDir){

      if(Math.abs(v) >= M.throwBackVelocity) return home;
    } else if(Math.abs(travel) >= M.flickDistance){

      const base = throwDir > 0 ? Math.max(home, Math.floor(at)) : Math.min(home, Math.ceil(at));
      return clamp(base + throwDir);
    }
  }

  if(Math.abs(startPos - start) > 0.02) return clamp(Math.round(at));
  if(far) return clamp(start + dragDir * Math.max(1, Math.round(Math.abs(travel) / s)));
  return start;
}

rankStep:
function rankStep(){
  const g = _rankCar.geom || rankMeasure();
  return (g && g.step) || 300;
}

rankRender:
function rankRender(pos){
  if(!(pos === pos)) return;                        
  _rankCar.pos = pos;
  const g = _rankCar.geom || rankMeasure();
  if(!g) return;
  const last = g.panels.length - 1;
  let shown = pos;
  if(pos < 0) shown = rankRubber(pos * g.step, g.step) / g.step;
  else if(pos > last) shown = last + rankRubber((pos - last) * g.step, g.step) / g.step;
  const inside = Math.max(0, Math.min(last, shown));
  const lo = Math.floor(inside), hi = Math.min(last, lo + 1), frac = inside - lo;
  const offset = g.offsets[lo] + (g.offsets[hi] - g.offsets[lo]) * frac + (shown - inside) * g.step;
  g.track.style.transform = 'translate3d(' + (g.center - offset).toFixed(2) + 'px,0,0)';


  const flat = rankReducedMotion();
  for(let i = 0; i <= last; i++){
    const d = Math.min(1, Math.abs(i - shown));
    const key = Math.round(d * 1000) + (flat ? 2000 : 0);
    const el = g.panels[i];
    if(el._rkDepth === key) continue;
    el._rkDepth = key;
    el.style.opacity = (1 - RANK_MOTION.depthFade * d).toFixed(3);
    el.style.transform = flat ? 'none' : 'scale(' + (1 - RANK_MOTION.depthScale * d).toFixed(4) + ')';
  }
  if(g.thumb && g.railWidth){
    g.thumb.style.transform = 'translate3d(' + (g.railWidth * (inside + 0.5) / g.panels.length).toFixed(2) + 'px,0,0)';
  }
  rankAtmosphereAt(lo, hi, frac);
  const nearest = Math.round(inside);
  if(nearest !== _rankCar.nearest){
    _rankCar.nearest = nearest;
    rankNearestChanged(nearest);
  }
}

rankAtmosphereAt:
function rankAtmosphereAt(lo, hi, frac){
  const a = _rankCar.atmos || (_rankCar.atmos = {
    base: document.getElementById('rankAtmosBase'),
    top: document.getElementById('rankAtmosBlend'), b: -1, t: -1, o: -1 });
  if(!a.base || !a.top) return;
  const f = frac < 0.002 ? 0 : frac > 0.998 ? 1 : frac;

  const cost = (baseRank, topRank, topWeight) =>
    (topWeight < 1 && a.b !== baseRank ? 1 : 0) + (topWeight > 0 && a.t !== topRank ? 1 : 0);
  const straight = cost(lo, hi, f) <= cost(hi, lo, 1 - f);
  const baseRank = straight ? lo : hi, topRank = straight ? hi : lo, w = straight ? f : 1 - f;
  if(w < 1 && a.b !== baseRank){ paintRankAtmosphere(baseRank, a.base); a.b = baseRank; }
  if(w > 0 && a.t !== topRank){ paintRankAtmosphere(topRank, a.top); a.t = topRank; }
  const o = Math.round(w * 1000) / 1000;
  if(o !== a.o){ a.o = o; a.top.style.opacity = String(o); }
}

rankNearestChanged:
function rankNearestChanged(i){
  const r = RANKS[i];
  if(!r) return;
  const cap = document.getElementById('rankRailPos');
  if(cap) cap.textContent = (i === _rankCar.mine ? 'YOU' : 'VIEWING') + ' · RANK ' + (i + 1) + ' OF ' + RANKS.length;
  const thumb = _rankCar.geom && _rankCar.geom.thumb;
  if(thumb && thumb.style && typeof thumb.style.setProperty === 'function'){
    const v = RANK_VISUALS[r.name] || RANK_VISUALS.ROOKIE;
    thumb.style.setProperty('--thumb-hi', mixHex(v.gem[0], '#FFFFFF', 0.45));
    thumb.style.setProperty('--thumb-lo', v.gem[1]);
    thumb.style.setProperty('--thumb-glow', hexA(v.gem[0], 0.55));
  }
  rankUpdateReturn(i);
}

rankRailHtml:
function rankRailHtml(p){
  const mine = rankIndexOf(p.rank);
  return RANKS.map((r, i) => {
    const state = i < mine ? 'achieved' : i === mine ? 'current' : 'locked';
    const said = state === 'current' ? 'your rank' : state === 'achieved' ? 'achieved' : 'not yet reached';
    return '<button type="button" class="rank-rail-seg is-' + state + '" onclick="rankGoTo(' + i + ')"' +
      ' aria-label="' + escapeAttr(r.name + ', rank ' + (i + 1) + ' of ' + RANKS.length + ', ' + said) + '">' +
      '<span class="rank-rail-bar" aria-hidden="true"></span>' +
      (state === 'current' ? '<span class="rank-rail-you" aria-hidden="true">YOU</span>' : '') +
    '</button>';
  }).join('') + '<span class="rank-rail-thumb" id="rankRailThumb" aria-hidden="true"></span>';
}

rankLanded:
function rankLanded(i, quiet){
  const car = _rankCar, g = car.geom;
  const arrived = !quiet && i !== car.landed;
  car.landed = i;
  if(g) g.panels.forEach((c, k) => c.classList.toggle('rank-front', k === i));
  document.querySelectorAll('.rank-rail-seg').forEach((s, k) => {
    if(k === i) s.setAttribute('aria-current', 'true'); else s.removeAttribute('aria-current');
  });
  if(!arrived) return;
  rankArrive(g ? g.panels[i] : null);
  const r = RANKS[i], live = document.getElementById('rankLive');
  if(live && r) live.textContent = r.name + ', rank ' + (i + 1) + ' of ' + RANKS.length + ', ' +
    (i === car.mine ? 'your rank' : i < car.mine ? 'achieved' : 'not yet reached');
}

rankArrive:
function rankArrive(panel, entrance){
  rankCancel('arrival');
  if(!panel || typeof panel.querySelector !== 'function') return;
  if(rankReducedMotion()) return;
  const el = panel.querySelector('.rank-medal-wrap img');
  if(!el || typeof el.animate !== 'function') return;
  const A = RANK_ARRIVE, made = [];
  try{
    made.push(el.animate([
      { opacity: entrance ? A.fadeFrom : 1, transform: 'scale(' + A.scaleFrom + ')' },
      { opacity: 1, transform: 'scale(1)' }
    ], { duration: A.settleMs, easing: 'cubic-bezier(0.2, 0, 0, 1)' }));
    const band = rankAssetsReady() ? panel.querySelector('.rank-sheen b') : null;
    if(band && typeof band.animate === 'function'){
      made.push(band.animate([
        { transform: 'translate3d(-130%, 0, 0)', opacity: 0 },
        { opacity: 1, offset: 0.22 },
        { transform: 'translate3d(240%, 0, 0)', opacity: 0 }
      ], { duration: A.sheenMs, delay: A.sheenDelayMs, easing: 'ease-in-out', fill: 'backwards' }));
    }
  }catch(e){}
  _rankCar.arrival = made.length ? made : null;
}

rankCancel:
function rankCancel(key){
  const a = _rankCar[key];
  (Array.isArray(a) ? a : [a]).forEach(x => { if(x){ try{ x.cancel(); }catch(e){} } });
  _rankCar[key] = null;
}

rankStopAnimation:
function rankStopAnimation(keepFade){
  const car = _rankCar;
  car.gen++;
  if(car.raf && typeof cancelAnimationFrame === 'function'){ try{ cancelAnimationFrame(car.raf); }catch(e){} }
  car.raf = 0;
  car.vel = 0;
  clearTimeout(car.watchdog);
  clearTimeout(car.jumpTimer);
  car.jumpTimer = 0;
  if(!keepFade) rankCancel('fades');
  rankCancel('arrival');    
}

rankAnimateTo:
function rankAnimateTo(target, vIndex){
  const car = _rankCar;
  rankStopAnimation(true);
  const gen = car.gen;
  const x0 = car.pos - target;
  if(rankReducedMotion() || typeof requestAnimationFrame !== 'function' ||
     (Math.abs(x0) < 0.0015 && Math.abs(vIndex || 0) < 0.00002)){
    rankRender(target);
    rankLanded(target);
    return;
  }
  const w = RANK_MOTION.omega;

  const cap = w * Math.abs(x0) * 1.15;
  const v0 = Math.max(-cap, Math.min(cap, (vIndex || 0) * 1000));
  const t0 = rankNow();
  let landed = false;
  const finish = () => {
    if(gen !== car.gen) return;
    car.gen++;                                      
    if(car.raf && typeof cancelAnimationFrame === 'function'){ try{ cancelAnimationFrame(car.raf); }catch(e){} }
    car.raf = 0; car.vel = 0;
    clearTimeout(car.watchdog);
    rankRender(target);
    if(!landed){ landed = true; rankLanded(target); }
  };
  const frame = () => {
    if(gen !== car.gen) return;

    if(car.depth > 2){ finish(); return; }
    car.depth++;
    try{
      const t = Math.max(0, (rankNow() - t0) / 1000);
      const s = rankSpringAt(x0, v0, t, w);
      if((Math.abs(s.x) < 0.0015 && Math.abs(s.v) < 0.02) || t > 1.2){ finish(); return; }
      car.vel = s.v / 1000;
      rankRender(target + s.x);
      if(!landed && Math.abs(s.x) < RANK_MOTION.commitDistance && Math.abs(s.v) < 0.6){
        landed = true;
        rankLanded(target);
      }
      car.raf = requestAnimationFrame(frame);
    } finally { car.depth--; }
  };

  car.watchdog = setTimeout(finish, 1400);
  car.raf = requestAnimationFrame(frame);
}

rankGoTo:
function rankGoTo(index, vIndex, glide){
  rankShowcaseIndex = Math.max(0, Math.min(RANKS.length - 1, index));
  const car = _rankCar;
  const v = vIndex === undefined ? (car.raf ? car.vel : 0) : vIndex;
  const at = Math.max(0, Math.min(RANKS.length - 1, car.pos));
  if(!glide && car.geom && !rankReducedMotion() && Math.abs(rankShowcaseIndex - at) >= 1.5) rankJumpTo(rankShowcaseIndex);
  else rankAnimateTo(rankShowcaseIndex, v);
}

rankGo:
function rankGo(delta){
  rankGoTo(Math.max(0, Math.min(RANKS.length - 1, rankShowcaseIndex + delta)), undefined, true);
}

rankUpdateReturn:
function rankUpdateReturn(view){
  const btn = document.getElementById('rankReturn');
  if(!btn) return;
  const away = view !== _rankCar.mine;
  btn.classList.toggle('is-shown', away);

  if(away) btn.classList.toggle('is-left', _rankCar.mine < view);
  btn.setAttribute('aria-hidden', away ? 'false' : 'true');
  btn.tabIndex = away ? 0 : -1;
}

rankReturnToMine:
function rankReturnToMine(){
  const btn = document.getElementById('rankReturn');

  if(btn && document.activeElement === btn){
    const wrap = document.getElementById('rankTrackWrap');
    if(wrap){ try{ wrap.focus({ preventScroll: true }); }catch(e){} }
  }
  rankGoTo(_rankCar.mine);
}

positionRankTrack:
function positionRankTrack(animate){
  if(animate){ rankGoTo(rankShowcaseIndex); return; }
  rankMeasure();
  if(_rankDrag || _rankCar.raf || _rankCar.jumpTimer){ rankRender(_rankCar.pos); return; }
  rankRender(rankShowcaseIndex);
  rankLanded(rankShowcaseIndex, true);
}

openRankShowcase:
function openRankShowcase(){
  const ov = document.getElementById('rankOverlay');
  if(!ov) return;
  if(ov.classList.contains('open')) return;       
  const p = getCurrentProgression();
  const track = document.getElementById('rankTrack');
  track.innerHTML = RANKS.map((r, i) => rankCardHtml(r, i, p)).join('');
  const rail = document.getElementById('rankRailTrack');
  if(rail) rail.innerHTML = rankRailHtml(p);
  const live = document.getElementById('rankLive');
  if(live) live.textContent = '';

  rankShowcaseIndex = rankIndexOf(p.rank);
  rankStopAnimation();
  Object.assign(_rankCar, { mine: rankShowcaseIndex, pos: rankShowcaseIndex,
    nearest: -1, landed: -1, geom: null, atmos: null });
  _rankDrag = null;
  ov.classList.add('open');
  document.body.classList.add('page-locked');
  positionRankTrack(false);
  rankUpdateReturn(rankShowcaseIndex);
  wireRankCarousel();

  rankWarmAssets();
  if(_rankCar.geom) rankArrive(_rankCar.geom.panels[rankShowcaseIndex], true);
}

closeRankShowcase:
function closeRankShowcase(){
  rankStopAnimation();
  rankCancel('arrival');
  _rankDrag = null;
  const ov = document.getElementById('rankOverlay');
  if(ov) ov.classList.remove('open');
  document.body.classList.remove('page-locked');
}

wireRankCarousel:
function wireRankCarousel(){
  const wrap = document.getElementById('rankTrackWrap');
  if(!wrap || wrap.dataset.wired === '1') return;
  wrap.dataset.wired = '1';
  wrap.addEventListener('pointerdown', e => {
    if(e.button > 0) return;
    if(_rankDrag && _rankDrag.mode === 'drag') return;    
    const moving = !!(_rankCar.raf || _rankCar.jumpTimer);

    if(moving) rankStopAnimation();

    _rankDrag = { id: e.pointerId, x0: e.clientX, xDown: e.clientX, y0: e.clientY, t0: rankNow(), dx: 0, lead: 0,
      mode: 'pending', startPos: _rankCar.pos, heading: rankShowcaseIndex, moving, samples: [{ t: rankNow(), x: e.clientX }] };
  });
  wrap.addEventListener('pointermove', e => {
    const d = _rankDrag;
    if(!d || e.pointerId !== d.id || d.mode === 'scroll') return;
    if(d.mode === 'pending'){
      const dx = e.clientX - d.xDown, dy = e.clientY - d.y0, ax = Math.abs(dx), ay = Math.abs(dy);
      if(ay >= RANK_MOTION.verticalSlop && ay >= ax * RANK_MOTION.verticalRatio){
        d.mode = 'scroll';                          
        return;
      }
      if(ax < RANK_MOTION.intentSlop || ax <= ay * RANK_MOTION.intentRatio){

        d.samples.push({ t: rankNow(), x: e.clientX });
        if(d.samples.length > 16) d.samples.shift();
        return;
      }

      d.mode = 'drag';
      d.lead = dx;
      d.x0 = e.clientX;
      wrap.classList.add('is-dragging');
      try{ wrap.setPointerCapture(e.pointerId); }catch(err){}
    }
    d.dx = e.clientX - d.x0;
    d.samples.push({ t: rankNow(), x: e.clientX });
    if(d.samples.length > 16) d.samples.shift();
    rankRender(d.startPos - d.dx / rankStep());
  });
  const release = e => {
    const d = _rankDrag;
    if(!d || e.pointerId !== d.id) return;
    _rankDrag = null;
    wrap.classList.remove('is-dragging');
    if(d.mode !== 'drag'){
      if(d.mode === 'pending' && e.type === 'pointerup' && !d.moving && rankNow() - d.t0 < 500){

        const g = _rankCar.geom;
        const hit = e.target && typeof e.target.closest === 'function' ? e.target.closest('.rank-panel') : null;
        const k = g && hit ? g.panels.indexOf(hit) : -1;
        if(k > -1 && Math.abs(k - rankShowcaseIndex) === 1){ rankGoTo(k); return; }
      }

      if(d.moving || Math.abs(_rankCar.pos - rankShowcaseIndex) > 0.001) rankGoTo(rankShowcaseIndex);
      return;
    }
    if(e.type !== 'pointerup'){

      rankGoTo(Math.max(0, Math.min(RANKS.length - 1, Math.round(_rankCar.pos))), 0, true);
      return;
    }
    const now = rankNow(), step = rankStep();
    const lastSample = d.samples[d.samples.length - 1];
    if(!lastSample || lastSample.x !== e.clientX){
      d.samples.push({ t: now, x: e.clientX });
      d.dx = e.clientX - d.x0;
    }
    const v = rankReleaseVelocity(d.samples, now);
    rankGoTo(rankSettleTarget(d.startPos, d.dx, v, step, d.heading, d.lead), -v / step, true);
  };
  wrap.addEventListener('pointerup', release);
  wrap.addEventListener('pointercancel', release);
  wrap.addEventListener('keydown', e => {
    if(e.key === 'ArrowRight'){ rankGo(1); e.preventDefault(); }
    if(e.key === 'ArrowLeft'){ rankGo(-1); e.preventDefault(); }
    if(e.key === 'Home'){ rankGoTo(0); e.preventDefault(); }
    if(e.key === 'End'){ rankGoTo(RANKS.length - 1); e.preventDefault(); }
  });

  const recentre = () => {
    const ov = document.getElementById('rankOverlay');
    if(!ov || !ov.classList.contains('open')) return;
    positionRankTrack(false);
  };
  window.addEventListener('resize', recentre);
  window.addEventListener('orientationchange', recentre);

  if(typeof ResizeObserver === 'function'){
    try{
      _rankCar.ro = new ResizeObserver(recentre);
      _rankCar.ro.observe(wrap);
    }catch(e){ _rankCar.ro = null; }
  }
}

rankIndexOf:
function rankIndexOf(name){
  return Math.max(0, RANKS.findIndex(r => r.name === name));
}

rankLevelRangeLabel:
function rankLevelRangeLabel(r){
  return r.max === Infinity ? ('Level ' + r.min + '+') : ('Level ' + r.min + '–' + r.max);
}

calculateRankFromLevel:
function calculateRankFromLevel(level){
  return (RANKS.find(r => level >= r.min && level <= r.max) || RANKS[RANKS.length-1]).name;
}

onboardingRankNow:
function onboardingRankNow(){
  try{ return getCurrentProgression().rank; }catch(e){ return RANKS[0].name; }
}

onboardingRankLadderHtml:
function onboardingRankLadderHtml(){
  const mine = onboardingRankNow();
  const cells = RANKS.map((r, i) => {
    const you = r.name === mine;
    const v = RANK_VISUALS[r.name] || RANK_VISUALS.ROOKIE;
    return '<li class="obr-cell' + (you ? ' is-you' : '') + '" style="--i:' + i + ';--obr-glow:' + hexA(v.gem[0], 0.3) + '"' +
        (you ? ' aria-current="true"' : '') + '>' +
      '<span class="obr-emb">' + rankMedalSvg(r.name, 64, { sheen: true }) + '</span>' +
      '<span class="obr-name">' + escapeHtml(r.name) + '</span>' +
      '<span class="obr-lvl">Level ' + r.min + '</span>' +
      (you ? '<span class="obr-you">YOU</span>' : '') +
    '</li>';
  }).join('');
  return '<div class="ob-mock ob-ranks">' +
      '<ol class="obr-grid" aria-label="The eight ranks, from Rookie to Legend">' + cells + '</ol>' +
      '<div class="ob-note">Earned by training — not by how much you lift.</div>' +
    '</div>';
}

rankMedalSvg:
function rankMedalSvg(rankName, size, opts){
  const o = opts || {};
  const file = RANK_EMBLEM_FILE[rankName] || RANK_EMBLEM_FILE.ROOKIE;
  const img = '<img class="rank-medal' + (o.showcase ? ' rank-medal-lg' : '') +
    '" src="' + file + '" width="' + size + '" height="' + size + '" alt="" decoding="async">';
  if(!o.showcase && !o.sheen) return img;

  return '<span class="rank-emblem-box">' + img +
    '<i class="rank-sheen" aria-hidden="true" style="-webkit-mask-image:url(' + file + ');mask-image:url(' + file + ')"><b></b></i></span>';
}
